-- PC-AC 2026: atualização normativa de identificação criminal e prisões, mais 10 questões.
with material as (
 select * from jsonb_to_recordset($material$[{"quiz":[{"a":false,"q":"A pessoa civilmente identificada nunca poderá ser submetida à identificação criminal.","why":"A Lei nº 12.037/2009 estabelece uma regra geral, mas prevê exceções. A Lei nº 15.295/2025 acrescentou novas hipóteses, inclusive relacionadas a crimes graves e sexuais."},{"a":true,"q":"A Lei nº 15.295/2025 acrescentou hipóteses de identificação criminal e de coleta de material biológico para perfil genético.","why":"A alteração entrou em vigor em janeiro de 2026. Ela acrescentou o inciso VII ao art. 3º e modificou o art. 5º da Lei nº 12.037/2009, com hipóteses específicas de coleta genética."},{"a":false,"q":"O flagrante presumido ocorre quando a pessoa é perseguida logo após a infração.","why":"A perseguição logo após, em situação que faça presumir autoria, caracteriza flagrante impróprio. O presumido ocorre quando a pessoa é encontrada logo depois com objetos ou instrumentos que indiquem autoria."},{"a":true,"q":"Ao receber o auto de flagrante, o juiz pode relaxar a prisão ilegal, converter em preventiva se presentes os requisitos ou conceder liberdade provisória.","why":"Essas são as três providências do art. 310. A conversão exige requisitos do art. 312 e demonstração de que medidas cautelares diversas são inadequadas ou insuficientes."},{"a":false,"q":"A autoridade policial pode decretar prisão preventiva quando entender que há risco de fuga.","why":"A autoridade policial pode representar pela preventiva, mas a decretação é ato do juiz, mediante provocação legítima, conforme art. 311 do CPP."},{"a":false,"q":"A gravidade abstrata do crime, isoladamente, é fundamento suficiente para a prisão preventiva.","why":"O art. 312, § 4º, incluído pela Lei nº 15.272/2025, exige demonstração concreta da periculosidade e do risco cautelar. A gravidade abstrata não basta."},{"a":true,"q":"A Lei nº 15.487/2026 incluiu no art. 313 hipótese de admissibilidade da preventiva para determinados crimes sexuais contra crianças e adolescentes.","why":"O inciso VI do art. 313 foi acrescentado pela Lei nº 15.487/2026, publicada em agosto de 2026, antes da data de corte do edital."},{"a":false,"q":"A prisão temporária pode ser decretada apenas porque o investigado não possui residência fixa.","why":"O STF afastou essa interpretação isolada. A temporária exige cinco requisitos cumulativos e não pode ser usada como prisão para averiguações."},{"a":true,"q":"A prisão temporária geral tem prazo de cinco dias, prorrogável por mais cinco em caso de extrema e comprovada necessidade.","why":"Esse é o prazo do art. 2º da Lei nº 7.960/1989. Para crimes hediondos e equiparados, existe prazo especial de 30 dias, prorrogável por mais 30."},{"a":true,"q":"O art. 310-A do CPP prevê coleta de material biológico em hipóteses específicas de prisão em flagrante.","why":"O dispositivo, incluído pela Lei nº 15.272/2025, trata de crimes específicos e exige coleta por agente treinado, com respeito à cadeia de custódia."},{"a":true,"q":"A prisão preventiva deve ser revista a cada 90 dias por decisão fundamentada.","why":"O art. 316, parágrafo único, prevê revisão periódica da necessidade de manutenção da preventiva. A revisão exige decisão fundamentada."},{"a":true,"q":"A monitoração eletrônica é uma medida cautelar diversa da prisão prevista no art. 319.","why":"A monitoração eletrônica consta expressamente do art. 319. É medida cautelar, não pena, e deve observar necessidade e adequação."}],"slug":"pcac-2026-processo-penal-09-identificacao-criminal-prisoes-medidas-cautelares","body_md":"# Identificação criminal, flagrante, prisões e medidas cautelares\n\n**Redação normativa considerada: legislação vigente até 06/11/2026, data de publicação do edital PC-AC.**\n\n## 1. Identificação criminal — Lei nº 12.037/2009\n\nA regra constitucional é simples: quem já está civilmente identificado não deve ser submetido à identificação criminal, salvo nas hipóteses previstas em lei. A identificação criminal não é punição; é procedimento de identificação, com garantias e finalidade própria.\n\nA Lei nº 12.037/2009 prevê documentos que comprovam a identificação civil e hipóteses em que a identificação criminal ainda pode ocorrer, como documento rasurado ou com indício de falsificação, insuficiência para identificar a pessoa, documentos conflitantes, uso de nomes diferentes ou necessidade essencial à investigação, esta última mediante decisão judicial fundamentada.\n\n### Atualização importante: Lei nº 15.295/2025\n\nApós 30 dias da publicação oficial em 22/12/2025, a Lei nº 15.295/2025 acrescentou hipóteses ao art. 3º, VII. Mesmo apresentado documento civil, pode haver identificação criminal após o recebimento da denúncia nas hipóteses legais que envolvem:\n- crime praticado com grave violência contra a pessoa;\n- crime contra a liberdade sexual ou crime sexual contra vulnerável;\n- determinados crimes do ECA relacionados à exploração e abuso sexual de crianças e adolescentes;\n- crime de organização criminosa armada, quando presentes as condições específicas do inciso.\n\nNas hipóteses do art. 3º, IV e VII, o art. 5º, § 1º, prevê também coleta de material biológico para obtenção do perfil genético. O § 2º prevê a coleta nos casos de prisão em flagrante decorrente dos crimes do inciso VII. A coleta deve seguir os procedimentos legais e técnicos; não se confunde com a simples identificação datiloscópica.\n\n## 2. Flagrante — CPP, arts. 301 a 310\n\nQualquer pessoa pode prender em flagrante; autoridades policiais e seus agentes têm o dever legal de fazê-lo (art. 301).\n\nO art. 302 apresenta quatro situações:\n- **Próprio:** a pessoa está cometendo a infração ou acaba de cometê-la (incisos I e II).\n- **Impróprio:** a pessoa é perseguida logo após, em situação que faça presumir ser autora (inciso III).\n- **Presumido:** a pessoa é encontrada logo depois com instrumentos, armas, objetos ou papéis que indiquem autoria (inciso IV).\n\nEm infração permanente, o flagrante dura enquanto não cessar a permanência (art. 303). A prisão deve ser formalizada, comunicada imediatamente e o auto encaminhado ao juiz em até 24 horas; no mesmo prazo, entrega-se a nota de culpa (art. 306).\n\n### Controle judicial — art. 310 atualizado\n\nO juiz deve realizar audiência de custódia em até 24 horas, atualmente prevista por videoconferência em tempo real, com presença do preso, defesa e Ministério Público. Depois de analisar a legalidade e as circunstâncias, deve fundamentar uma das providências:\n1. relaxar a prisão ilegal;\n2. converter o flagrante em preventiva, se presentes os requisitos do art. 312 e se as cautelares diversas forem inadequadas ou insuficientes;\n3. conceder liberdade provisória, com ou sem fiança.\n\n### Atualização da Lei nº 15.272/2025\n\nO art. 310, § 5º, passou a indicar circunstâncias que podem recomendar a conversão do flagrante em preventiva, sem dispensar a análise concreta: reiteração de infrações, violência ou grave ameaça, prática de infração durante investigação ou ação penal, fuga ou risco de fuga e perigo à instrução ou à preservação da prova, entre outras hipóteses legais. O § 6º exige decisão fundamentada e análise expressa dos critérios legais pertinentes.\n\nA mesma lei incluiu o art. 310-A, que prevê, em hipóteses específicas de flagrante (como crimes violentos, sexuais, organização criminosa armada e crimes hediondos), requerimento de coleta de material biológico para perfil genético. A coleta deve observar a cadeia de custódia e ser feita preferencialmente na audiência ou em até 10 dias.\n\n### Atualização da Lei nº 15.358/2026\n\nA Lei nº 15.358/2026 alterou o art. 310, caput e acrescentou parágrafos sobre audiência de custódia por videoconferência, privacidade, entrevista reservada com a defesa e providências em caso de falha técnica. A regra é a videoconferência; a realização presencial fica reservada às situações excepcionais previstas em lei e justificadas pelo juiz.\n\n## 3. Prisão preventiva — CPP, arts. 311 a 316\n\nA preventiva é decretada pelo juiz, em qualquer fase da investigação ou do processo, mediante requerimento do Ministério Público, querelante ou assistente, ou representação da autoridade policial (art. 311). O juiz não a decreta de ofício.\n\n### Requisitos — art. 312\n\nÉ necessário reunir:\n- prova da existência do crime;\n- indício suficiente de autoria;\n- perigo concreto gerado pelo estado de liberdade do imputado;\n- finalidade cautelar legal: garantia da ordem pública ou econômica, conveniência da instrução ou assegurar a aplicação da lei penal.\n\nA decisão deve apontar fatos concretos, novos ou contemporâneos. Não basta repetir a gravidade abstrata do delito.\n\nA Lei nº 15.272/2025 acrescentou critérios para avaliar a periculosidade, como modo de execução, violência reiterada, premeditação, participação em organização criminosa, natureza e quantidade de drogas/armas e risco concreto de reiteração. O § 4º deixa expresso que a gravidade abstrata, sozinha, não autoriza preventiva.\n\n### Hipóteses de admissibilidade — art. 313\n\nAlém dos requisitos do art. 312, a lei exige uma hipótese de admissibilidade. Entre elas:\n- crime doloso com pena máxima superior a quatro anos;\n- condenação anterior por outro crime doloso, observada a regra legal;\n- violência doméstica e familiar nas condições previstas no inciso III, para garantir medidas protetivas;\n- **inciso V, incluído pela Lei nº 15.358/2026:** crime praticado por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto legal;\n- **inciso VI, incluído pela Lei nº 15.487/2026:** crimes contra a dignidade sexual praticados contra criança ou adolescente e crimes específicos dos arts. 240 a 241-D e 244-A do ECA.\n\nA dúvida sobre identidade civil também pode justificar a preventiva nas condições do § 1º, mas a pessoa deve ser colocada em liberdade após identificação, salvo se outra hipótese legal recomendar a manutenção.\n\n### Fundamentação e revisão — arts. 314 a 316\n\nNão cabe preventiva se os elementos demonstrarem legítima defesa, estado de necessidade ou estrito cumprimento do dever legal/exercício regular de direito (art. 314). A decisão precisa ser concretamente fundamentada (art. 315). O juiz revoga a medida quando desaparecerem seus motivos e pode decretá-la novamente se surgirem razões novas. O art. 316, parágrafo único, prevê revisão fundamentada da necessidade da prisão a cada 90 dias.\n\n## 4. Prisão temporária — Lei nº 7.960/1989\n\nÉ medida cautelar decretada pelo juiz, a partir de representação da autoridade policial ou requerimento do Ministério Público. A autoridade policial não decreta prisão temporária.\n\nO art. 1º contém hipóteses legais específicas, incluindo imprescindibilidade para a investigação e fundadas razões de autoria ou participação em crimes do rol legal. O rol de crimes não pode ser ampliado por analogia.\n\n**Prazo geral:** 5 dias, prorrogáveis por mais 5 em caso de extrema e comprovada necessidade. Para crimes hediondos e equiparados, a Lei nº 8.072/1990 prevê 30 dias, prorrogáveis por mais 30 em caso de extrema e comprovada necessidade.\n\n### Critérios cumulativos fixados pelo STF — ADIs 3.360 e 4.109\n\nAlém da leitura da lei, o STF exige cumulativamente:\n1. imprescindibilidade concreta para a investigação, sem conjecturas ou prisão para averiguações;\n2. fundadas razões de autoria/participação em crime do rol legal, sem analogia;\n3. fatos novos ou contemporâneos;\n4. adequação à gravidade concreta, circunstâncias do fato e condições pessoais;\n5. insuficiência de medidas cautelares diversas.\n\nA ausência de residência fixa, sozinha, não basta para justificar a prisão temporária.\n\n## 5. Medidas cautelares diversas — CPP, arts. 282 e 319\n\nToda cautelar deve observar necessidade e adequação. O art. 319 prevê, entre outras medidas:\n- comparecimento periódico em juízo;\n- proibição de acesso a lugares ou contato com pessoas;\n- proibição de ausentar-se da comarca;\n- recolhimento domiciliar noturno e nos dias de folga;\n- suspensão de função ou atividade;\n- internação provisória nas hipóteses legais;\n- fiança;\n- monitoração eletrônica.\n\nA prisão é medida extrema: deve ser justificada a insuficiência das alternativas. Medida cautelar não é pena antecipada.\n\n## 6. Quadro de revisão rápida\n\n| Instituto | Quem decreta | Base principal | Ideia-chave |\n|---|---|---|---|\n| Flagrante | Captura por qualquer pessoa; dever das autoridades | CPP 301–310 | Situação de flagrância e controle judicial |\n| Preventiva | Juiz, mediante provocação | CPP 311–316 | Requisitos concretos + admissibilidade |\n| Temporária | Juiz, mediante representação/requerimento | Lei 7.960/1989 | Investigação, rol legal e prazo próprio |\n| Cautelares diversas | Juiz | CPP 282 e 319 | Necessidade e adequação |\n\n## 7. Pegadinhas para a IDECAN\n\n- Civilmente identificado não significa identificação criminal absolutamente proibida: existem exceções legais, atualizadas pela Lei nº 15.295/2025.\n- Flagrante próprio, impróprio e presumido são situações diferentes do art. 302.\n- A autoridade policial representa pela preventiva; quem decreta é o juiz.\n- A preventiva não pode se apoiar apenas na gravidade abstrata.\n- O art. 313 contém hipóteses de admissibilidade; o art. 312 traz os requisitos cautelares.\n- A temporária não é prisão para averiguação e exige cinco requisitos cumulativos fixados pelo STF.\n- A revisão da preventiva ocorre a cada 90 dias, com decisão fundamentada.\n- Perfil genético, identificação datiloscópica e fotografia são procedimentos diferentes; atenção às alterações de 2025 e 2026.","flashcards":[{"b":"Não deve ser submetido à identificação criminal, salvo nas hipóteses legais da Lei nº 12.037/2009.","f":"Qual é a regra para quem já possui identificação civil?"},{"b":"Foram acrescentadas hipóteses de identificação criminal após recebimento da denúncia e hipóteses de coleta de material biológico para perfil genético.","f":"O que mudou na Lei nº 12.037/2009 com a Lei nº 15.295/2025?"},{"b":"Próprio (cometendo ou acaba de cometer), impróprio (perseguido logo após) e presumido (encontrado logo depois com objetos indicativos).","f":"Quais são as três modalidades clássicas de flagrante do art. 302?"},{"b":"Relaxar prisão ilegal, converter em preventiva se preenchidos os requisitos, ou conceder liberdade provisória com ou sem fiança.","f":"Quais são as três decisões possíveis do juiz no art. 310?"},{"b":"Circunstâncias que podem recomendar a conversão em preventiva, exigência de análise fundamentada e coleta de material biológico em hipóteses específicas.","f":"O que a Lei nº 15.272/2025 acrescentou ao art. 310?"},{"b":"O juiz, mediante requerimento do MP, querelante ou assistente, ou representação da autoridade policial. Não pode decretar de ofício.","f":"Quem pode decretar prisão preventiva?"},{"b":"Prova da existência do crime, indício suficiente de autoria e perigo concreto decorrente do estado de liberdade, com finalidade cautelar legal.","f":"Quais são os requisitos centrais do art. 312?"},{"b":"Critérios concretos para avaliar periculosidade e vedação de preventiva fundada apenas na gravidade abstrata do delito.","f":"O que a Lei nº 15.272/2025 acrescentou ao art. 312?"},{"b":"Inciso V: organização criminosa ultraviolenta, grupo paramilitar ou milícia privada nas condições legais; inciso VI: determinados crimes sexuais contra crianças/adolescentes e crimes do ECA.","f":"Quais incisos novos foram incluídos no art. 313 em 2026?"},{"b":"5 dias, prorrogáveis por mais 5 em extrema e comprovada necessidade; crimes hediondos e equiparados têm prazo especial de 30 + 30 dias.","f":"Qual é o prazo geral da prisão temporária?"},{"b":"Imprescindibilidade concreta, fundadas razões em crime do rol, fatos novos/contemporâneos, adequação e insuficiência de cautelares diversas.","f":"Quais são os cinco requisitos cumulativos do STF para a prisão temporária?"},{"b":"A cada 90 dias, mediante decisão fundamentada, conforme art. 316, parágrafo único.","f":"Qual é a periodicidade de revisão da prisão preventiva?"}],"legal_basis":[{"url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","title":"Código de Processo Penal — texto atualizado, Câmara dos Deputados"},{"url":"https://www2.camara.leg.br/legin/fed/lei/2009/lei-12037-1-outubro-2009-591435-normaatualizada-pl.html","title":"Lei nº 12.037/2009 — texto atualizado, Câmara dos Deputados"},{"url":"https://www2.camara.leg.br/legin/fed/lei/1989/lei-7960-21-dezembro-1989-365581-normaatualizada-pl.html","title":"Lei nº 7.960/1989 — texto atualizado, Câmara dos Deputados"},{"url":"https://www2.camara.leg.br/legin/fed/lei/2025/lei-15272-26-novembro-2025-798356-norma-pl.html","title":"Lei nº 15.272/2025 — alterações no CPP"},{"url":"https://www2.camara.leg.br/legin/fed/lei/2026/lei-15358-24-marco-2026-798846-norma-pl.html","title":"Lei nº 15.358/2026 — Marco Legal do Combate ao Crime Organizado"},{"url":"https://www2.camara.leg.br/legin/fed/lei/2026/lei-15487-6-agosto-2026-799703-norma-pl.html","title":"Lei nº 15.487/2026 — alterações no art. 313 do CPP"},{"url":"https://www2.camara.leg.br/legin/fed/lei/2025/lei-15295-19-dezembro-2025-798507-norma-pl.html","title":"Lei nº 15.295/2025 — alterações na identificação criminal"},{"url":"https://portal.stf.jus.br/noticias/verNoticiaDetalhe.asp?idConteudo=481715&tip=UN","title":"STF — ADIs 3.360 e 4.109: critérios cumulativos da prisão temporária"},{"url":"https://sead.ac.gov.br/wp-content/uploads/2026/11/Edital-no-001-PCAC-Edital-de-abertura-05-11-2026.pdf","title":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III"}],"source_note":"Edital nº 001 SEAD/PCAC, de 05/11/2026, Anexo III, p. 48. Legislação e jurisprudência conferidas em 14/11/2026, considerando a data de corte do edital em 06/11/2026.","legal_review":{"notes":"Atualizados art. 310 e 310-A, arts. 312 e 313, identificação criminal após Lei 15.295/2025, critérios cumulativos do STF para prisão temporária e prazos. Todas as alterações consideradas estavam vigentes antes da publicação do edital em 06/11/2026.","status":"reviewed_against_official_updated_text","sources":["CPP — Câmara dos Deputados","Lei 12.037/2009 — Câmara dos Deputados","Lei 7.960/1989 — Câmara dos Deputados","Leis 15.272/2025, 15.358/2026, 15.487/2026","STF ADIs 3360 e 4109"],"cutoff_date":"2026-11-06","review_date":"2026-11-14"}}]$material$::jsonb)
 as x(slug text,body_md text,source_note text,legal_basis jsonb,legal_review jsonb,flashcards jsonb,quiz jsonb)
)
update public.study_materials sm
set body_md=m.body_md,source_note=m.source_note,legal_basis=m.legal_basis,legal_review=m.legal_review,
    flashcards=m.flashcards,quiz=m.quiz,law_version_checked_at=now(),reviewed_at=now()
from material m where sm.slug=m.slug;

insert into public.curated_question_catalog
(source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance)
select source_id,syllabus_topic_id,external_item_key,contest_name,contest_year,career_name,exam_board,subject,subtopic,tested_topic,question_text,official_answer,explanation,legal_basis,difficulty,content_status,is_original,didactic_provenance
from jsonb_to_recordset($questions$[{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Lei nº 12.037/2009 após Lei nº 15.295/2025","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A Lei nº 15.295/2025 acrescentou o inciso VII ao art. 3º da Lei nº 12.037/2009. A identificação criminal pode ocorrer após o recebimento da denúncia em hipóteses taxativas, como crime praticado com grave violência contra a pessoa. Não é uma autorização geral para identificar qualquer investigado.","is_original":true,"legal_basis":["Lei nº 12.037/2009, art. 3º, VII; Lei nº 15.295/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Identificação criminal — art. 3º, VII","question_text":"Após a alteração promovida pela Lei nº 15.295/2025, a identificação criminal do civilmente identificado pode ocorrer, entre outras hipóteses, após o recebimento da denúncia por:\n\nA) qualquer contravenção penal, sem outra condição.\nB) qualquer crime culposo patrimonial.\nC) qualquer infração de menor potencial ofensivo.\nD) crime praticado com grave violência contra a pessoa, nas condições do art. 3º, VII, da Lei nº 12.037/2009.\nE) qualquer crime, desde que o delegado considere conveniente.","content_status":"active","official_answer":"D","external_item_key":"pcac26-penal-proc-211-lei15295-identificacao","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Coleta de material biológico na identificação criminal","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A alteração da Lei nº 15.295/2025 acrescentou os §§ 1º e 2º ao art. 5º. A coleta genética está vinculada às hipóteses legais dos incisos IV e VII do art. 3º e aos flagrantes pelos crimes do inciso VII. Não é coleta automática em toda abordagem ou identificação criminal.","is_original":true,"legal_basis":["Lei nº 12.037/2009, art. 5º, §§ 1º e 2º; Lei nº 15.295/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Lei nº 12.037/2009 — art. 5º, §§ 1º e 2º","question_text":"Nos termos do art. 5º da Lei nº 12.037/2009, com a redação da Lei nº 15.295/2025, a identificação criminal incluirá coleta de material biológico para obtenção do perfil genético:\n\nA) em toda abordagem policial, mesmo sem hipótese legal.\nB) nas hipóteses dos incisos IV e VII do art. 3º e, também, nos flagrantes decorrentes dos crimes referidos no inciso VII.\nC) somente após condenação definitiva.\nD) apenas quando o investigado autorizar voluntariamente.\nE) sempre que houver identificação fotográfica, independentemente da hipótese.","content_status":"active","official_answer":"B","external_item_key":"pcac26-penal-proc-212-lei15295-dna","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Audiência de custódia — art. 310 atualizado","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A Lei nº 15.358/2026 alterou o caput do art. 310 para prever audiência de custódia em até 24 horas por videoconferência em tempo real, com a presença do acusado, defensor e Ministério Público. A lei admite exceções específicas para a forma presencial, mas não elimina a participação da defesa.","is_original":true,"legal_basis":["CPP, art. 310, caput; Lei nº 15.358/2026"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 310, caput","question_text":"Conforme a redação do art. 310 do CPP dada pela Lei nº 15.358/2026, a audiência de custódia deve ocorrer:\n\nA) em até 24 horas após a prisão, por videoconferência em tempo real como regra, com participação do preso, defesa e Ministério Público.\nB) somente depois de 5 dias, sem participação da defesa.\nC) apenas presencialmente, sendo vedada a videoconferência.\nD) em até 72 horas, apenas com a autoridade policial.\nE) somente quando o preso solicitar.","content_status":"active","official_answer":"A","external_item_key":"pcac26-penal-proc-213-art310-videoconferencia","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 310, § 5º: circunstâncias para conversão do flagrante","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O § 5º apresenta circunstâncias que recomendam a conversão, sem criar conversão automática. O § 6º exige decisão motivada e análise dos critérios legais. Continuam necessários os pressupostos da preventiva e a demonstração de inadequação ou insuficiência das cautelares diversas.","is_original":true,"legal_basis":["CPP, art. 310, §§ 5º e 6º; Lei nº 15.272/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 310, §§ 5º e 6º","question_text":"Segundo o art. 310, § 5º, do CPP, incluído pela Lei nº 15.272/2025, as circunstâncias ali enumeradas:\n\nA) obrigam o juiz a converter toda prisão em flagrante em preventiva, automaticamente.\nB) dispensam os requisitos do art. 312.\nC) podem recomendar a conversão em preventiva, mas exigem análise fundamentada das circunstâncias concretas e dos requisitos legais.\nD) autorizam a autoridade policial a decretar preventiva.\nE) transformam o flagrante em prisão temporária.","content_status":"active","official_answer":"C","external_item_key":"pcac26-penal-proc-214-art310-par5-circunstancias","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 310-A: coleta de perfil genético","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 310-A não institui coleta indiscriminada em todo flagrante. Ele lista hipóteses específicas, como crimes com violência ou grave ameaça, crimes contra a dignidade sexual, organização criminosa armada e crimes hediondos. A coleta deve respeitar a cadeia de custódia e ser feita por agente treinado.","is_original":true,"legal_basis":["CPP, art. 310-A e §§ 1º e 2º; Lei nº 15.272/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 310-A","question_text":"O art. 310-A do CPP, incluído pela Lei nº 15.272/2025, prevê requerimento de coleta de material biológico para obtenção e armazenamento do perfil genético:\n\nA) em toda prisão em flagrante, sem distinção de crime.\nB) apenas em contravenções penais.\nC) somente depois do trânsito em julgado da condenação.\nD) sem necessidade de cadeia de custódia ou agente treinado.\nE) em hipóteses específicas de flagrante previstas no dispositivo, com coleta por agente público treinado e observância da cadeia de custódia.","content_status":"active","official_answer":"E","external_item_key":"pcac26-penal-proc-215-art310a-perfil-genetico","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 312, § 3º: critérios de periculosidade","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 312, § 3º, orienta a análise da periculosidade com elementos concretos, como modo de execução, participação em organização criminosa, natureza e quantidade de drogas ou armas e fundado receio de reiteração. Opinião pública e repercussão midiática não substituem fundamentação concreta.","is_original":true,"legal_basis":["CPP, art. 312, § 3º; Lei nº 15.272/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 312, § 3º","question_text":"A Lei nº 15.272/2025 acrescentou critérios para aferição da periculosidade do agente na análise da prisão preventiva. Entre eles está:\n\nA) o modus operandi, inclusive uso reiterado de violência ou grave ameaça e premeditação.\nB) a repercussão negativa do caso na imprensa, isoladamente.\nC) a opinião pública sobre o investigado.\nD) a gravidade abstrata do tipo penal, sem fatos concretos.\nE) a ausência de confissão.","content_status":"active","official_answer":"A","external_item_key":"pcac26-penal-proc-216-art312-periculosidade","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 312, § 4º: gravidade abstrata","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O § 4º proíbe a prisão preventiva fundada apenas na gravidade abstrata do delito. A decisão deve demonstrar, com elementos concretos do caso, a periculosidade do agente e o risco à ordem pública, econômica, à instrução ou à aplicação da lei penal.","is_original":true,"legal_basis":["CPP, art. 312, § 4º; Lei nº 15.272/2025"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 312, § 4º","question_text":"De acordo com o art. 312, § 4º, do CPP, incluído pela Lei nº 15.272/2025:\n\nA) a gravidade abstrata do crime basta para decretar preventiva.\nB) a preventiva é obrigatória em todo crime doloso.\nC) a decisão pode dispensar a demonstração de perigo concreto.\nD) é incabível decretar preventiva com base apenas na gravidade abstrata; devem ser demonstrados concretamente a periculosidade e o risco cautelar.\nE) a preventiva pode ser decretada para antecipar a pena.","content_status":"active","official_answer":"D","external_item_key":"pcac26-penal-proc-217-art312-gravidade-abstrata","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 313, incisos V e VI: novas hipóteses","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A Lei nº 15.358/2026 acrescentou o inciso V, e a Lei nº 15.487/2026 acrescentou o inciso VI. São hipóteses de admissibilidade, não dispensam os requisitos cautelares do art. 312 e devem ser lidas nos limites exatos do texto legal.","is_original":true,"legal_basis":["CPP, art. 313, V e VI; Leis nº 15.358/2026 e 15.487/2026"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 313, V e VI","question_text":"Considerando as alterações de 2026 no art. 313 do CPP, assinale a alternativa correta.\n\nA) Os incisos V e VI autorizam preventiva sem os requisitos do art. 312.\nB) O inciso V trata de integrantes de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada nas condições legais; o inciso VI abrange determinados crimes sexuais contra crianças/adolescentes e crimes especificados do ECA.\nC) O inciso VI permite preventiva em qualquer crime praticado contra adulto.\nD) O inciso V trata apenas de contravenções com arma branca.\nE) Os dois incisos foram revogados antes da publicação do edital.","content_status":"active","official_answer":"B","external_item_key":"pcac26-penal-proc-218-art313-v-vi","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Art. 316: revisão da prisão preventiva","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O art. 316, parágrafo único, determina revisão a cada 90 dias, por decisão fundamentada e de ofício. A finalidade é verificar se os motivos cautelares continuam presentes. A revisão não é mera formalidade: exige análise atual da necessidade da prisão.","is_original":true,"legal_basis":["CPP, art. 316, parágrafo único"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"CPP — art. 316, parágrafo único","question_text":"Após a decretação da prisão preventiva, o órgão emissor da decisão deve revisar a necessidade de sua manutenção:\n\nA) a cada 30 dias, por despacho administrativo.\nB) somente quando a defesa pedir.\nC) a cada 90 dias, mediante decisão fundamentada, de ofício.\nD) apenas depois da sentença.\nE) uma única vez, após a audiência de custódia.","content_status":"active","official_answer":"C","external_item_key":"pcac26-penal-proc-219-art316-revisao-90dias","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}},{"subject":"Noções de Direito Penal e Processual Penal","subtopic":"Prisão temporária: cinco requisitos cumulativos do STF","source_id":"b2a15f6c-7cad-417c-8407-67e33fc9dc47","difficulty":"alta","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O STF estabeleceu cinco requisitos cumulativos: necessidade concreta para a investigação; fundadas razões de autoria ou participação em crime do rol taxativo; contemporaneidade; adequação à gravidade concreta e condições pessoais; e insuficiência de cautelares diversas. Prisão para averiguações ou fundada só na falta de residência fixa é vedada.","is_original":true,"legal_basis":["Lei nº 7.960/1989, art. 1º; STF, ADIs 3.360 e 4.109"],"contest_name":"Polícia Civil do Acre","contest_year":2026,"tested_topic":"Lei nº 7.960/1989 — ADIs 3.360 e 4.109","question_text":"Segundo o STF nas ADIs 3.360 e 4.109, a prisão temporária exige, cumulativamente:\n\nA) apenas ausência de residência fixa e requerimento policial.\nB) gravidade abstrata do delito e repercussão social.\nC) mera suspeita, ainda que o crime não esteja no rol legal.\nD) requerimento do delegado, sem decisão judicial.\nE) imprescindibilidade concreta, fundadas razões em crime do rol legal, fatos novos ou contemporâneos, adequação e insuficiência de cautelares diversas.","content_status":"active","official_answer":"E","external_item_key":"pcac26-penal-proc-220-temporaria-cinco-requisitos-stf","syllabus_topic_id":"e5ccace6-4479-4921-adf0-4ed63aa607a8","didactic_provenance":{"kind":"original_question","source":"Edital nº 001 SEAD/PCAC, de 05/11/2026 — Anexo III","cutoff_date":"2026-11-06","review_date":"2026-11-14","review_note":"Questão autoral; alternativa única e explicação revisadas contra legislação vigente antes da publicação do edital.","legal_sources":["CPP atualizado","Leis 15.295/2025, 15.272/2025, 15.358/2026 e 15.487/2026","STF ADIs 3360 e 4109"]}}]$questions$::jsonb)
